{
  "critique": [
    {
      "design": "r0A",
      "good": "All headers and values remain on one line, making rows compact and identifiers easy to follow. The first viewport contains the product identification, variant and quantity fields.",
      "problems": "The table requires substantial horizontal scrolling to reach the financial and fulfillment fields. Price begins at the viewport edge, so it is only partially visible.",
      "cause": "The 157px SKU and 143px Warehouse columns reserve space for their longest values on one line; together with the 180px Tracking column, they make the table 862px wide."
    },
    {
      "design": "r0B",
      "good": "SKU values wrap at hyphens without splitting segments, while headers, amounts and tracking identifiers remain intact. The extra row height keeps each line item visually coherent, and the table is narrower than r0A.",
      "problems": "Price is cut off at the right edge of the first viewport. Readers still need to scroll a considerable distance to reach warehouse and tracking information.",
      "cause": "The first five columns use 308px, leaving less than the 62px required for Price. The 102px Warehouse and 180px Tracking columns preserve readable fulfillment information but extend the table."
    },
    {
      "design": "r0C",
      "good": "Most of the table lies near the viewport, reducing horizontal travel.",
      "problems": "Headers, identifiers, colors and monetary amounts break into fragments. Tall rows and uneven text make both cross-row comparison and following a line item difficult.",
      "cause": "Widths of 38–51px leave only 17–30px for text in most columns. Even the 50px Tracking column is far narrower than its 159px unbreakable value."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "price-in-view",
      "widths": [38, 99, 61, 52, 47, 62, 53, 68, 102, 180],
      "change": "Narrow SKU by 11px from r0B so the first six columns total 359px and Price fits in the initial viewport. Preserve the other readable widths and use natural SKU wrapping."
    },
    {
      "name": "compact-fulfillment",
      "widths": [38, 99, 61, 52, 47, 62, 53, 68, 102, 180],
      "change": "Keep Warehouse at its 102px minimum for the intact header and Tracking at 180px for the intact identifier, while allowing warehouse values and SKUs to wrap at natural breaks."
    }
  ]
}
